INSERT INTO `currency_types` (`ID`, `Name`, `Description`, `CategoryID`, `InventoryIconFileID`, `SpellWeight`, `SpellCategory`, `MaxQty`, `MaxEarnablePerWeek`, `Quality`, `FactionID`, `ItemGroupSoundsID`, `XpQuestDifficulty`, `AwardConditionID`, `MaxQtyWorldStateID`, `RechargingAmountPerCycle`, `RechargingCycleDurationMS`, `AccountTransferPercentage`, `OrderIndex`, `RecraftReagentCountPercentage`, `OrderSource`, `MCRCurrencyID`, `Flags1`, `Flags2`, `VerifiedBuild`) VALUES
(3356, 'Untainted Mana-Crystals', 'Can be earned after reaching rank 9 of the Delver\'s Journey. May be obtained from opening Bountiful Coffers with Restored Coffer Keys inside of bountiful delves at Tier 11. Can be traded with Zah\'ran for powerful equipment.', 281, 5931199, 0, 0, 1000, 250, 4, 0, 0, 0, 156185, 0, 0, 0, 0, 0, 0, 0, 0, 100671490, 0, 69497),
(3418, 'Nebulous Voidcore', 'Transmutable into powerful equipment upon defeating powerful foes in Midnight raids or completing Mythic+ dungeons, Bountiful Delves and Prey Hunts on Nightmare difficulty. \n\nItems may be received once per difficulty level until all potential items for your current specialization have been transmuted.', 264, 7658129, 0, 0, 0, 0, 4, 0, 0, 0, 0, 32183, 0, 0, 0, 40, 0, 0, 0, 33816706, 1, 69497),
(3509, 'Tidal Spark Dust', 'Magical residue obtained alongside Sparks of Tides. Used to track how many Sparks of Tides you have obtained so far in Midnight Season 2.\n\nIf you fall behind on Sparks during the season, completing max-level content such as Delves, Mythic Plus, Raids, Instanced PvP, and some outdoor events may help you catch up.', 264, 5929576, 0, 0, 3, 0, 4, 0, 24, 0, 0, 32659, 0, 0, 0, 30, 0, 0, 0, 68681728, 1, 69497);
